INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 19, 'theory', 'Квиз: CSS — Flexbox');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 19, 0, 'Какое свойство задаёт направление главной оси флекс-контейнера?', '["align-items","flex-direction","justify-content","flex-wrap"]', 1, 'flex-direction выбирает направление главной оси: row, row-reverse, column или column-reverse. justify-content и align-items лишь выравнивают элементы вдоль главной и поперечной осей, а flex-wrap разрешает перенос строк.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 19, 1, 'Контейнер шириной 600px, три элемента с flex-basis 100px и flex-grow: 1 у каждого. Какой станет ширина элемента?', '["100px: база не меняется","300px","600px","200px"]', 3, 'Занято 300px, свободно 300px. Три одинаковые доли дают по 100px, и каждый элемент вырастает со 100px до 200px. Рост считается от базы, а не от нуля.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 19, 2, 'Чем сокращение flex: 1 отличается от flex: auto?', '["У flex: 1 база равна нулю, у flex: auto — размеру содержимого","flex: 1 запрещает сжатие, а flex: auto разрешает","flex: 1 включает перенос строк","Ничем, это синонимы"]', 0, 'flex: 1 раскрывается в 1 1 0%: место делится строго по долям. flex: auto — это 1 1 auto: элемент сначала получает размер по содержимому, а потом делит остаток. Поэтому при flex: auto ширины колонок могут быть разными.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 19, 3, 'Длинное слово в флекс-элементе вылезает за границу контейнера. Что исправит это?', '["align-items: stretch","justify-content: space-between","min-width: 0 у элемента (и overflow с text-overflow, если текст нужно обрезать)","order: -1"]', 2, 'Минимальная ширина флекс-элемента по умолчанию равна ширине его содержимого, поэтому ниже длинного слова он не сжимается. min-width: 0 снимает это ограничение; для обрезки с многоточием добавляют скрытое переполнение, text-overflow и white-space: nowrap.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 19, 4, 'Почему свойством order нельзя менять смысловой порядок содержимого?', '["В мобильных браузерах он не работает","Клавиатурный фокус и скринридер идут по порядку разметки, и картинка расходится с тем, что слышит и чем управляет пользователь","Он отключает flex-grow у соседей","Он меняет порядок элементов в DOM, и скрипты ломаются"]', 1, 'order меняет только отображение. Табуляция и программы чтения с экрана читают разметку, поэтому фокус будет прыгать по странице вразнобой. Порядок в разметке должен быть осмысленным, а order и row-reverse годятся для косметики.');
